using System.Linq;
using NUnit.Framework;
using LWS.TruckJenga;
public sealed class JengaRulesTests
{
    [TestCase(2)][TestCase(3)][TestCase(4)]public void LegalSelectionAndClearanceReleaseRestAreRequiredBeforeSingleStack(int players){var r=new JengaRules(players);Assert.That(r.Count,Is.EqualTo(18));Assert.That(r.BeginPull(0,4),Is.False);r.FoundationReady();Assert.That(r.LegalPieces().All(p=>r.Row(p)<5),Is.True);Assert.That(r.BeginPull(1,4),Is.False);Assert.That(r.BeginPull(0,17),Is.False);Assert.That(r.BeginPull(0,4),Is.True);Assert.That(r.BeginPull(0,7),Is.False);Assert.That(r.Extracted(4,false),Is.False);Assert.That(r.Stacks.Sum(),Is.Zero);Assert.That(r.Extracted(4,true),Is.True);Assert.That(r.Restacked(4,false),Is.False);Assert.That(r.Restacked(4,true),Is.True);Assert.That(r.Row(4),Is.EqualTo(6));Assert.That(r.Column(4),Is.Zero);Assert.That(r.Restacked(4,true),Is.False);Assert.That(r.Stacks[0],Is.EqualTo(1));Assert.That(r.NextTurn(false),Is.False);Assert.That(r.NextTurn(true),Is.True);Assert.That(r.Owner,Is.EqualTo(1));Assert.That(r.Responsible,Is.Zero);}
    [Test]public void NextTopLayerFillsThreeSlotsBeforeAddingAnother(){var r=new JengaRules(2);r.FoundationReady();for(int n=0;n<4;n++){int p=JengaSelection.Careful(r);Assert.That(p,Is.GreaterThanOrEqualTo(0));Assert.That(r.BeginPull(r.Owner,p),Is.True);Assert.That(r.Extracted(p,true),Is.True);r.NextSlot(out int row,out int column);Assert.That(row,Is.EqualTo(n<3?6:7));Assert.That(column,Is.EqualTo(n%3));Assert.That(r.Restacked(p,true),Is.True);r.NextTurn(true);}Assert.That(r.Stacks.Sum(),Is.EqualTo(4));}
    [Test]public void CollapseBelongsToLastPhysicalPullerIncludingNextSelectionAndOnlyLocksOnce(){var r=new JengaRules(4);Assert.That(r.Collapse(true),Is.False);r.FoundationReady();Assert.That(r.Collapse(true),Is.False);r.BeginPull(0,4);r.Extracted(4,true);r.Restacked(4,true);r.NextTurn(true);Assert.That(r.Owner,Is.EqualTo(1));Assert.That(r.Collapse(false),Is.False);Assert.That(r.Collapse(true),Is.True);Assert.That(r.Loser,Is.Zero);Assert.That(r.Collapse(true),Is.False);Assert.That(r.BeginPull(1,7),Is.False);Assert.That(r.Stacks.Sum(),Is.EqualTo(1));}
    [Test]public void ActualNextPullAcquiresResponsibilityAndResetHasNoHistoricalScore(){var r=new JengaRules(2);r.FoundationReady();r.BeginPull(0,4);r.Extracted(4,true);r.Restacked(4,true);r.NextTurn(true);r.BeginPull(1,7);r.Collapse(true);Assert.That(r.Loser,Is.EqualTo(1));var fresh=new JengaRules(2);Assert.That(fresh.Stacks.Sum(),Is.Zero);Assert.That(fresh.Responsible,Is.EqualTo(-1));Assert.That(fresh.Phase,Is.EqualTo(JengaRules.Stage.Preparing));}
    [Test]public void CarefulAiUsesPublicOccupancyAndAvoidsRemovingSecondSupportWhileIntactRowsExist(){var r=new JengaRules(2);r.FoundationReady();int first=JengaSelection.Careful(r);Assert.That(r.Column(first),Is.EqualTo(1));Assert.That(r.Row(first),Is.EqualTo(1));r.BeginPull(0,first);r.Extracted(first,true);r.Restacked(first,true);r.NextTurn(true);int next=JengaSelection.Careful(r);Assert.That(r.Column(next),Is.EqualTo(1));Assert.That(r.Row(next),Is.Not.EqualTo(1));}
}
